hooks.command:
node -e "
const p = process.env.CLAUDE_TOOL_INPUT_FILE_PATH || process.env.CLAUDE_TOOL_INPUT_PATH || '';
const agents = [
  { pattern: /src[\\/](components|pages|index\.css)/, agent: 'SmartCart-Frontend', note: 'UI change: verify tap targets (44px), pb-24 padding, Spanish strings, no direct supabase import' },
  { pattern: /supabase[\\/]/, agent: 'SmartCart-Backend', note: 'Schema change: add RLS policy, never edit existing migrations, create new NNN_verb_noun.sql' },
  { pattern: /src[\\/]services[\\/]/, agent: 'SmartCart-Integrations', note: 'Service change: add JSDoc @returns, throw on error, use offlineQueue for writes' },
  { pattern: /\.(test|spec)\.(js|jsx|ts|tsx)$/, agent: 'SmartCart-QA', note: 'Test file: run audit checklist in .agents/SmartCart-QA.md before committing' },
];
const match = agents.find(a => a.pattern.test(p));
if (match) console.log('[SmartCart] Agent domain: ' + match.agent + ' | ' + match.note);
"

node -e "
const p = process.env.CLAUDE_TOOL_INPUT_FILE_PATH || process.env.CLAUDE_TOOL_INPUT_PATH || '';
if (/supabase[\\/]migrations/.test(p)) {
  console.log('[SmartCart-Backend] Migration written. Reminder: (1) verify RLS policies, (2) notify SmartCart-Integrations of schema changes, (3) run: supabase db push');
}
if (/src[\\/]services/.test(p)) {
  console.log('[SmartCart-Integrations] Service written. Reminder: (1) JSDoc on all public methods, (2) update hook if return shape changed, (3) notify SmartCart-Frontend of new hook API');
}
if (/src[\\/](components|pages)/.test(p)) {
  console.log('[SmartCart-Frontend] Component written. Reminder: run SmartCart-QA audit checklist before marking this interface done');
}
"
